def compute(vars):
    dividends_2018 = vars["v1"]
    dividends_2019 = vars["v2"]
    nominal_difference = dividends_2019 - dividends_2018
    return {
        "value": nominal_difference,
        "trace": {
            "v1": dividends_2018,
            "v2": dividends_2019,
            "calculation": "v2 - v1",
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
